import {encodeBroadcast,decodeBroadcast} from './net-codec.js';
export function validateCloudConfig(config){let u;try{u=new URL(config.url);}catch{throw Error('Inserisci l’URL del progetto Supabase.');}if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co'))throw Error('Usa l’URL HTTPS del progetto Supabase, non quello dell’organizzazione.');const key=String(config.publishableKey||'').trim();if(key.startsWith('sb_secret_'))throw Error('Usa una chiave publishable: le chiavi segrete non vanno nel gioco.');if(key.startsWith('eyJ')){try{const role=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role;if(role!=='anon')throw Error('secret');}catch{throw Error('Usa una chiave publishable o anon, mai service_role.');}}else if(!/^sb_publishable_[\w-]{12,}$/.test(key))throw Error('Inserisci la chiave publishable del progetto Supabase.');u.pathname='/';u.search='';u.hash='';return{url:u.origin,publishableKey:key};}
export class RealtimeLink{
 constructor(config,handlers={},socketFactory=url=>new WebSocket(url)){this.config=validateCloudConfig(config);this.handlers=handlers;this.factory=socketFactory;this.socket=null;this.topic=null;this.joinRef='';this.ref=0;this.pending=new Map();this.presence={};this.bytes={tx:0,rx:0};this.closed=false;this.heartbeat=null;}
 count(data,direction){this.bytes[direction]+=typeof data==='string'?new TextEncoder().encode(data).length:data.byteLength||data.size||0;}
 wire(data){if(this.socket?.readyState!==1)return false;this.count(data,'tx');this.socket.send(data);return true;}
 text(event,payload={},topic=this.topic,reference=null){const ref=reference??String(++this.ref);this.wire(JSON.stringify([topic?this.joinRef:null,ref,topic||'phoenix',event,payload]));return ref;}
 connect(){const u=new URL(this.config.url);u.protocol='wss:';u.pathname='/realtime/v1/websocket';u.searchParams.set('apikey',this.config.publishableKey);u.searchParams.set('vsn','2.0.0');this.closed=false;
  return new Promise((resolve,reject)=>{const ws=this.socket=this.factory(u.href);ws.binaryType='arraybuffer';let settled=false;const fail=message=>{if(!settled){settled=true;clearTimeout(timeout);reject(Error(message));}},timeout=setTimeout(()=>{fail('Supabase non risponde. Controlla URL, chiave e connessione.');this.close();},12000);ws.onopen=()=>{settled=true;clearTimeout(timeout);this.heartbeat=setInterval(()=>this.text('heartbeat',{},null),20000);resolve(this);};ws.onerror=()=>fail('Connessione Supabase non riuscita.');ws.onclose=()=>{clearInterval(this.heartbeat);for(const request of this.pending.values()){clearTimeout(request.timer);request.reject(Error('Connessione chiusa'));}this.pending.clear();fail('Connessione Supabase chiusa.');if(!this.closed)this.handlers.onClose?.();};ws.onmessage=async e=>{this.count(e.data,'rx');let data=e.data;if(typeof Blob!=='undefined'&&data instanceof Blob)data=await data.arrayBuffer();if(typeof data!=='string'){const b=decodeBroadcast(data);if(b&&b.topic===this.topic)this.handlers.onBroadcast?.(b.event,b.payload);return;}let m;try{m=JSON.parse(data);}catch{return;}const [join,ref,topic,event,payload]=Array.isArray(m)?m:[m.join_ref,m.ref,m.topic,m.event,m.payload];if(event==='phx_reply'){const request=this.pending.get(ref);if(request){this.pending.delete(ref);clearTimeout(request.timer);payload.status==='ok'?request.resolve(payload.response):request.reject(Error(payload.response?.message||payload.response?.reason||'Ingresso nella stanza rifiutato.'));}return;}if(topic!==this.topic)return;if(event==='broadcast')this.handlers.onBroadcast?.(payload.event,payload.payload);else if(event==='presence_state'){this.presence=payload;this.handlers.onPresence?.(this.presence);}else if(event==='presence_diff'){for(const[k,v]of Object.entries(payload.joins||{})){const old=this.presence[k]?.metas||[];const incoming=v.metas||[];this.presence[k]={metas:[...old.filter(m=>!incoming.some(n=>n.phx_ref===m.phx_ref)),...incoming]};}for(const[k,v]of Object.entries(payload.leaves||{})){if(!this.presence[k])continue;const refs=new Set((v.metas||[]).map(m=>m.phx_ref));this.presence[k].metas=this.presence[k].metas.filter(m=>!refs.has(m.phx_ref));if(!this.presence[k].metas.length)delete this.presence[k];}this.handlers.onPresence?.(this.presence);}else if(event==='phx_error'||event==='phx_close')this.handlers.onError?.('La stanza Supabase è stata chiusa.');};});
 }
 async join(code,id,metadata){await this.leave();this.topic='realtime:apexgp:'+code;this.joinRef=String(++this.ref);const ref=this.joinRef;const promise=new Promise((resolve,reject)=>{const timer=setTimeout(()=>{this.pending.delete(ref);reject(Error('La stanza non risponde.'));},15000);this.pending.set(ref,{resolve,reject,timer});});this.text('phx_join',{config:{broadcast:{ack:false,self:false},presence:{enabled:true,key:id},private:false}},this.topic,ref);await promise;this.track(metadata);}
 track(metadata){if(this.topic)this.text('presence',{type:'presence',event:'track',payload:metadata});}
 control(payload){if(!this.topic)return false;return this.wire(JSON.stringify([this.joinRef,null,this.topic,'broadcast',{type:'broadcast',event:'c',payload}]));}
 pose(payload){if(!this.topic||this.socket?.bufferedAmount>8192)return false;return this.wire(encodeBroadcast(this.topic,'p',payload,this.joinRef,String(++this.ref)));}
 async leave(){if(this.topic&&this.socket?.readyState===1)this.text('phx_leave',{});this.topic=null;this.presence={};}
 close(){this.closed=true;clearInterval(this.heartbeat);this.heartbeat=null;this.leave();this.socket?.close();this.socket=null;}
}
